const respuesta = $input.first().json.output;
const sessionId = $('Webhook').first().json.body.sessionId;

try {
  const datos = typeof respuesta === 'string'
    ? JSON.parse(
        respuesta.trim()
          .replace(/^```(?:json)?\s*/i, '')
          .replace(/\s*```$/, '')
      )
    : respuesta;

  const p = datos.propuesta;

  if (typeof datos.mensaje !== 'string') {
    throw new Error('Respuesta invalida');
  }

  const completa = p &&
    typeof sessionId === 'string' &&
    sessionId.trim() &&
    typeof p.nombre === 'string' &&
    p.nombre.trim() &&
    typeof p.correo === 'string' &&
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.correo) &&
    Number.isInteger(p.personas) &&
    p.personas > 0 &&
    /^\d{4}-\d{2}-\d{2}$/.test(p.fecha) &&
    /^\d{2}:\d{2}$/.test(p.hora) &&
    Number.isInteger(p.numero_mesa) &&
    p.numero_mesa >= 1 &&
    p.numero_mesa <= 5;

  const propuesta = completa ? {
    nombre: p.nombre,
    correo: p.correo,
    personas: p.personas,
    fecha: p.fecha,
    hora: p.hora,
    numero_mesa: p.numero_mesa
  } : null;

  const token = completa ? JSON.stringify({
    proposal_id: 'PROP-' + $execution.id,
    sessionId: sessionId,
    expira_en: Date.now() + 15 * 60 * 1000,
    propuesta: propuesta
  }) : null;

  return [{
    json: {
      output: p && !completa
        ? 'No pude preparar la propuesta correctamente.'
        : datos.mensaje,
      propuesta: propuesta,

    }
  }];

} catch (error) {
  return [{
    json: {
      output: 'No pude preparar la respuesta.',
      propuesta: null,
      token_propuesta: null
    }
  }];
}

const body = $input.first().json.body;
const p = body.propuesta;

function rechazar(mensaje) {
  return [{ json: { valido: false, output: mensaje } }];
}

if (body.confirmado !== true) {
  return rechazar('La reserva no fue confirmada.');
}

if (typeof body.sessionId !== 'string' || !body.sessionId.trim()) {
  return rechazar('Sesion invalida.');
}

if (!p) {
  return rechazar('No se recibieron los datos de la reserva.');
}

if (
  typeof p.nombre !== 'string' || !p.nombre.trim() ||
  typeof p.correo !== 'string' ||
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.correo) ||
  !Number.isInteger(p.personas) || p.personas < 1 ||
  !Number.isInteger(p.numero_mesa) ||
  p.numero_mesa < 1 || p.numero_mesa > 5 ||
  !/^\d{4}-\d{2}-\d{2}$/.test(p.fecha) ||
  !/^([01]\d|2[0-3]):[0-5]\d$/.test(p.hora)
) {
  return rechazar('Los datos de la reserva son invalidos.');
}

const inicio = new Date(`${p.fecha}T${p.hora}:00-05:00`);

if (
  !Number.isFinite(inicio.getTime()) ||
  inicio.getTime() <= Date.now()
) {
  return rechazar('La fecha u hora de la reserva no es valida.');
}

return [{
  json: {
    valido: true,
    nombre: p.nombre.trim(),
    correo: p.correo.trim(),
    personas: p.personas,
    fecha: p.fecha,
    hora: p.hora,
    numero_mesa: p.numero_mesa,
    session_id: body.sessionId
  }
}];

const p = $('Validar_Datos_Reserva').first().json;

const mesas = $('Verificar_Mesa').all().map(i => i.json);
const reservas = $input.all().map(i => i.json);

function rechazar(mensaje) {
  return [{
    json: {
      disponible: false,
      output: mensaje
    }
  }];
}

// Duracion de cada reserva en minutos
const duracion = 120;

// Convertir horas a minutos
function minutos(hora) {
  const texto = String(hora).trim();

  if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(texto)) {
    return NaN;
  }

  const [h, m] = texto.split(':').map(Number);
  return h * 60 + m;
}

// Buscar la mesa solicitada
const coincidencias = mesas.filter(m =>
  Number(m.numero_mesa) === p.numero_mesa
);

if (coincidencias.length !== 1) {
  return rechazar('No se pudo identificar la mesa.');
}

const mesa = coincidencias[0];

// Verificar estado operativo
if (
  String(mesa.estado_mesa).trim().toLowerCase()
  !== 'disponible'
) {
  return rechazar('La mesa no esta disponible.');
}

// Verificar capacidad
if (
  !Number.isInteger(Number(mesa.capacidad)) ||
  Number(mesa.capacidad) < p.personas
) {
  return rechazar('La mesa no tiene capacidad suficiente.');
}

// Verificar que la fecha exista
const fecha = new Date(p.fecha + 'T00:00:00Z');

if (
  !Number.isFinite(fecha.getTime()) ||
  fecha.toISOString().slice(0, 10) !== p.fecha
) {
  return rechazar('La fecha no es valida.');
}

// Calcular horario solicitado
const inicio = minutos(p.hora);
const fin = inicio + duracion;

// Horario del restaurante: 14:00 a 23:00
if (
  !Number.isFinite(inicio) ||
  inicio < 14 * 60 ||
  fin > 23 * 60
) {
  return rechazar('Horario fuera del servicio del restaurante.');
}

// Comprobar conflictos con reservas existentes
for (const r of reservas) {

  // Ignorar salida vacia de Google Sheets
  if (Object.keys(r).length === 0) continue;

  const estado = String(r.estado).trim().toLowerCase();

  if (estado === 'cancelada') continue;

  if (Number(r.numero_mesa) !== p.numero_mesa) continue;

  const inicioExistente = minutos(r.hora);
  const finExistente = inicioExistente + duracion;

  if (!Number.isFinite(inicioExistente)) {
    return rechazar('No se pudo verificar un horario existente.');
  }

  if (inicio < finExistente && fin > inicioExistente) {
    return rechazar(
      'La mesa ya tiene una reserva en ese horario.'
    );
  }
}

// Generar codigo de reserva
const codigo = 'RES-' +
  p.fecha.replace(/-/g, '') + '-' +
  $execution.id;

// Preparar datos para Google Sheets
return [{
  json: {
    disponible: true,
    codigo: codigo,
    nombre: p.nombre,
    correo: p.correo,
    personas: p.personas,
    fecha: p.fecha,
    hora: p.hora,
    numero_mesa: p.numero_mesa,
    estado: 'Confirmada',
    calendar_event_id: '',
    estado_calendar: 'Pendiente',
    estado_correo: 'Pendiente',
    session_id: p.session_id
  }
}];

